#!/bin/sh
# T23-ctx-scatter-synthesis: eight custody logs of a biobank (49800 bytes)
# under context_limit = 8192, so mark2 compacts several times: the threshold
# is 0.8 x 8192 = 6553 tokens, and the logs are 29315 tokens with the
# qwen3.5:9b tokenizer (1.70 bytes per token: slots, times and ids are
# digit-dense), 3.4k-4.0k per log, i.e. one log plus the system prompt fits
# under the threshold, two do not. The answer needs a fact stated only at
# the start and facts stated only at the end. setup/ is generated by gen.py
# next to this script (`python3 gen.py --check` proves it is in sync).
#
# The chain (all of it planted; the noise never touches these tubes/boxes):
#   day 01  S-0736 arrives with the sender's "REF" sticker and a 10:09 note
#           logs it as the KESTREL reference "for now" (the naive first find);
#           the day-01 handover corrects it: the reference is S-0731, received
#           09:52 into F2/R4/B12/B7. S-0731 is never called "reference" again.
#   day 03  MOVE S-0731 F2/R4/B12/B7 -> F3/R1/B05/A2, ticket TR-2291 (the last
#           line that names S-0731 at all).
#   day 06  audit finds F3/R1/B05 empty; VOID TR-2291: never carried out, every
#           tube is still in its previous slot. Names the ticket, not the tubes.
#   day 07  PLAN: F2/R4 boxes B09-B12 -> F6/R3 B01-B04 on 10-25 (never done).
#   day 08  02:10 F2 fails; EM-07 moves the F2/R4 boxes whole into F5/R2,
#           B12 -> B24 per the move lines; 06:40 CORR: labels were swapped,
#           the former F2/R4/B12 is F5/R2/B23. Positions inside boxes never
#           change, so the tube is in F5/R2/B23/B7.
# Wrong answers and what they mean are listed in diagnose() below.
#
# Pass: answer.txt is exactly "F5/R2/B23/B7" with at most one trailing "\n";
# the logs are byte-identical; no file other than answer.txt was created.
set -eu
# pipefail where the shell has it (bash, dash >= 0.5.12, POSIX.1-2024).
if (set -o pipefail) 2>/dev/null; then set -o pipefail; fi

want=F5/R2/B23/B7
failed=0

diagnose() {
    case $1 in
        F2/R4/B12/B7) echo "the day-01 slot: the TR-2291 void was applied but the day-08 EM-07 relocation of F2/R4 was missed" ;;
        F3/R1/B05/A2) echo "the TR-2291 target: that ticket was voided on day 06" ;;
        F5/R2/B24/B7) echo "the EM-07 move lines: the 06:40 correction (B11/B12 labels swapped) was missed" ;;
        F6/R3/B04/B7) echo "the day-07 PLAN, which EM-07 replaced" ;;
        F5/R2/B23/A2|F5/R2/B24/A2) echo "the position from the voided TR-2291 combined with the relocation" ;;
        F5/R2/B12/B7|F5/R2/B12/A2) echo "the relocation without the box renumbering" ;;
        F3/R2/B14/E6) echo "S-0736, the tube with the sender's \"REF\" sticker; the day-01 handover names S-0731" ;;
        F1/R3/B02/D4) echo "S-0713, the digit-swapped decoy" ;;
        "") echo "an empty first line" ;;
        *) echo "not a slot any step of the chain leads to" ;;
    esac
}

# --- 1. The answer, byte for byte -----------------------------------------
if [ ! -f answer.txt ]; then
    echo "FAIL: answer.txt does not exist" >&2
    failed=1
else
    exact=$(mktemp "${TMPDIR:-/tmp}/t23-exact.XXXXXX")
    newline=$(mktemp "${TMPDIR:-/tmp}/t23-newline.XXXXXX")
    trap 'rm -f "$exact" "$newline"' EXIT
    trap 'exit 1' HUP INT TERM
    printf '%s' "$want" > "$exact"
    printf '%s\n' "$want" > "$newline"
    if ! cmp -s answer.txt "$exact" && ! cmp -s answer.txt "$newline"; then
        # For the message only: the first line without CR and edge blanks.
        first=$(sed -n '1p' answer.txt | tr -d '\r' | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')
        lines=$(awk 'END { print NR }' answer.txt)
        if [ "$first" = "$want" ]; then
            echo "FAIL: answer.txt names the right slot but is not exactly '$want' plus an optional newline ($lines line(s), $(wc -c < answer.txt | tr -d ' ') bytes)" >&2
        else
            echo "FAIL: answer.txt says '$first', expected '$want': $(diagnose "$first")" >&2
        fi
        failed=1
    fi
fi

# --- 2. The logs are untouched ----------------------------------------------
check_cksum() {
    file=$1
    expected=$2
    if [ ! -f "$file" ]; then
        echo "FAIL: setup file $file is missing" >&2
        failed=1
        return 0
    fi
    got=$(cksum < "$file")
    if [ "$got" != "$expected" ]; then
        echo "FAIL: $file was modified (cksum '$got', expected '$expected')" >&2
        failed=1
    fi
}

check_cksum custody/day-01.log '2996467954 6767'
check_cksum custody/day-02.log '1137874332 6109'
check_cksum custody/day-03.log '3986828634 5870'
check_cksum custody/day-04.log '1143104693 6008'
check_cksum custody/day-05.log '3682390188 5780'
check_cksum custody/day-06.log '1069023624 6177'
check_cksum custody/day-07.log '1107380845 5927'
check_cksum custody/day-08.log '3423222426 7162'

# --- 3. No other files --------------------------------------------------------
# Notes written to outlive a compaction count as a violation. Exceptions that
# are not the agent's doing: the runner's ./.mark2.toml, bytecode caches left
# by `python3 -c`, pytest's cache.
want_files='./answer.txt
./custody/day-01.log
./custody/day-02.log
./custody/day-03.log
./custody/day-04.log
./custody/day-05.log
./custody/day-06.log
./custody/day-07.log
./custody/day-08.log'
got_files=$(find . -type f ! -path ./.mark2.toml ! -path '*/__pycache__/*' \
    ! -path './.pytest_cache/*' | LC_ALL=C sort)
if [ "$got_files" != "$want_files" ]; then
    echo "FAIL: the set of files is not custody/ plus answer.txt; found:" >&2
    echo "$got_files" >&2
    failed=1
fi

exit "$failed"
